mapper.update:
UPDATE documents SET status = 'ready', error = NULL, reader_needed = NULL, reader_task = NULL,
        text_len = #{textLen},
        chunk_count = #{chunkCount}, updated_at = now() WHERE id = #{id}

UPDATE documents SET status = 'failed', error = #{error}, reader_needed = #{reader},
        reader_task = NULL, updated_at = now()
 WHERE id = #{id}

mapper.select:
SELECT sha256, deleted_at IS NOT NULL AS tombstoned
  FROM documents WHERE id = #{id}
 FOR NO KEY UPDATE

mapper.update:
UPDATE chunks SET seq = #{seq}, char_start = #{charStart}, char_end = #{charEnd},
        doc_version = #{version}, heading = #{heading}
 WHERE id = #{id}

UPDATE documents SET graph_status = 'queued', graph_error = NULL,
        extract_epoch = extract_epoch + 1
 WHERE id = #{id}

mapper.select:
SELECT * FROM documents
 WHERE source_id = #{sourceId} AND external_key IS NULL AND filename = #{filename}
   AND deleted_at IS NULL LIMIT 1
